using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using CrystalParkour;using FirstPerson;
public static class CrystalParkourScenarios
{
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Call(object target,string method){target.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)?.Invoke(target,null);}
 public static object Run()
 {
  Check(!Application.isPlaying,"Run deterministic physics/animation checks in Edit Mode");var previous=SceneManager.GetActiveScene();var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(scene);var cases=new List<string>();CrystalTraversal p=null;GauntletCombat combat=null;WindVolume wind=null;
  try
  {
   var go=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/CrystalParkour/Prefabs/CrystalParkourPlayer.prefab"));go.name="Isolated traversal validation";p=go.GetComponent<CrystalTraversal>();var motor=go.GetComponent<FirstPersonMotor>();combat=go.GetComponent<GauntletCombat>();Call(motor,"Awake");Call(go.GetComponent<FirstPersonVitals>(),"Awake");Call(combat,"Awake");Call(p,"Awake");Call(p,"OnEnable");Call(combat.actions.motion,"Awake");
   var origin=new Vector3(400,20,400);
   void Place(Vector3 pos,Quaternion rotation){p.Drop("Test reset");motor.Body.enabled=false;go.transform.position=pos;motor.Body.enabled=true;motor.SetLookRotation(rotation);motor.StopMomentum();combat.Cancel();p.Tick(.6f,false);Physics.SyncTransforms();}
   GameObject Box(string name,Vector3 position,Vector3 size){var box=GameObject.CreatePrimitive(PrimitiveType.Cube);box.name=name;box.transform.position=position;box.transform.localScale=size;return box;}
   Place(origin,Quaternion.identity);var target=Box("Crystal surface",origin+new Vector3(0,1.65f,6),new Vector3(3,3,.25f));var crystal=target.AddComponent<CrystalSurface>();crystal.contact=target.GetComponent<Collider>();Call(crystal,"Awake");Physics.SyncTransforms();
   Check(p.TryFindSurface(out var hit,out var found)&&found==crystal,"Crystal detection failed");
   var blocker=Box("Ordinary obstruction",origin+new Vector3(0,1.6f,3),new Vector3(4,4,.3f));Physics.SyncTransforms();Check(!p.TryFindSurface(out _,out _),"Tether passed through a solid ordinary wall");UnityEngine.Object.DestroyImmediate(blocker);Physics.SyncTransforms();cases.Add("Component detection accepts crystal surfaces and stops at ordinary occluders");
   combat.Press();combat.Tick(.5f);Check(p.BeginTether(crystal,hit.point,hit.normal),"Remote tether did not start");Check(p.State==CrystalTraversal.Mode.Pulling&&p.AttachedElapsed==0,"Timer began during remote pull");
   p.Tick(.1f,true);Check(p.AttachedElapsed==0,"Travel consumes the attachment timer");for(int i=0;i<12&&p.State==CrystalTraversal.Mode.Pulling;i++)p.Tick(.05f,true);
   Check(p.State==CrystalTraversal.Mode.Attached,"Pull failed to reach contact range");Check(motor.MovementSuspended&&p.AttachedElapsed==0,"Attachment does not suspend normal falling");p.Tick(1.9f,true);Check(p.State==CrystalTraversal.Mode.Attached,"Attachment expired before two seconds");p.Tick(.11f,true);Check(p.State==CrystalTraversal.Mode.Free&&!motor.MovementSuspended,"Two-second timeout did not release");p.Tick(.6f,true);Check(p.State==CrystalTraversal.Mode.Free,"Holding through timeout automatically reattached forever");cases.Add("Pull does not consume the timer; contact expires after two seconds and requires a fresh charge");
   Place(origin+new Vector3(0,0,4.8f),Quaternion.identity);combat.Press();combat.Tick(1.1f);Check(p.BeginTether(crystal,target.GetComponent<Collider>().ClosestPoint(p.aim.position),Vector3.back),"Close tether failed");Check(p.State==CrystalTraversal.Mode.Attached,"Close target did not attach");p.Tick(1.95f,true);int before=p.Rebounds;combat.Release();Check(p.State==CrystalTraversal.Mode.AwaitingImpact&&p.Rebounds==before,"Release launched before the hit frame");combat.Tick(.02f);Check(p.Rebounds==before,"Wind-up generated a launch");combat.Tick(.09f);Check(p.Rebounds==before+1,"Actual gauntlet hit did not rebound");Check(Vector3.Dot(p.LastLaunchVelocity,Vector3.back)>0&&p.LastLaunchVelocity.y>0,"Rebound does not point away and up");var launch=motor.Velocity;motor.Tick(.1f);Check(Vector3.ProjectOnPlane(motor.Velocity,Vector3.up).magnitude>7,"Original movement overwrote the launch momentum");Check(!p.BeginTether(crystal,hit.point,hit.normal),"Same surface immediately reacquired");cases.Add("Release at 1.95 seconds waits for native hitboxes, then launches once and preserves momentum");
   Place(origin,Quaternion.Euler(85,0,0));var ground=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/CrystalParkour/Prefabs/CrystalGrowth_Ground.prefab"));ground.transform.position=origin-Vector3.up*.02f;var site=ground.GetComponent<CrystalGrowthSite>();Call(site,"Awake");Physics.SyncTransforms();combat.Press();combat.Release();combat.Tick(.07f);Check(!site.HasGrown,"Ground crystal grew during wind-up");combat.Tick(.14f);Check(site.HasGrown&&p.GrewFloor,"Floor strike did not grow the crystal");Check(!site.Finished&&site.growthRoot.GetComponentsInChildren<Collider>(true).All(c=>!c.enabled),"Growing colliders trapped the player before completion");site.Tick(site.duration);Check(site.Finished&&site.growthRoot.GetComponentsInChildren<Collider>(true).All(c=>c.enabled),"Final platform colliders not restored");cases.Add("Floor growth occurs at the real punch frame, lifts the attacker and enables colliders only when ready");
   Place(origin+new Vector3(0,0,12),Quaternion.Euler(0,90,0));var wall=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/CrystalParkour/Prefabs/CrystalGrowth_Wall.prefab"));wall.transform.position=go.transform.position+new Vector3(1.25f,1.4f,0);var wallSite=wall.GetComponent<CrystalGrowthSite>();Call(wallSite,"Awake");Physics.SyncTransforms();combat.Press();combat.Release();combat.Tick(.2f);Check(wallSite.HasGrown&&p.GrewWall,"Wall strike did not grow a platform");wallSite.Tick(wallSite.duration);Check(Vector3.Dot(wallSite.growthRoot.transform.up,Vector3.up)>.99f,"Wall growth did not keep a horizontal standing surface");Check(go.transform.position.y>=wallSite.growthRoot.GetComponent<Collider>().bounds.max.y,"Wall crystal grew into the player capsule");cases.Add("Wall impact grows a horizontal shelf and lifts the attacker clear of the final collider");
   Place(origin+new Vector3(20,10,0),Quaternion.identity);var windGo=new GameObject("Validation updraft",typeof(BoxCollider),typeof(WindVolume));windGo.transform.position=go.transform.position+Vector3.up;windGo.GetComponent<BoxCollider>().size=Vector3.one*10;wind=windGo.GetComponent<WindVolume>();wind.acceleration=19;Call(wind,"Awake");Call(wind,"OnEnable");p.Tick(.2f,false);motor.Tick(.5f);float inWind=motor.Velocity.y;Check(inWind>-2&&p.UsedWind,"Updraft did not counter gravity");motor.Body.enabled=false;go.transform.position+=Vector3.right*20;motor.Body.enabled=true;p.Tick(.4f,false);motor.Tick(.5f);Check(motor.ExternalAcceleration.magnitude<.001f&&motor.Velocity.y<-9,"Exiting wind did not restore gravity");cases.Add("Wind cancels most gravity inside the volume and blends out after leaving");
   Place(origin+new Vector3(40,10,15),Quaternion.identity);var droneGo=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/CrystalParkour/Prefabs/TraversalDronePlaceholder.prefab"));droneGo.transform.position=go.transform.position;var drone=droneGo.GetComponent<TraversalDrone>();drone.moving=false;Call(drone,"Start");var bounds=drone.deck.bounds;motor.Body.enabled=false;go.transform.position=new Vector3(bounds.center.x+.9f,bounds.max.y,bounds.center.z);motor.Body.enabled=true;var standing=go.transform.position;droneGo.transform.position+=Vector3.forward*.4f;Call(drone,"Update");Check(p.RodeDrone&&Vector3.ProjectOnPlane(go.transform.position-standing-Vector3.forward*.4f,Vector3.up).magnitude<.02f&&Mathf.Abs(go.transform.position.y-standing.y)<=motor.Body.skinWidth+.02f,"Moving drone did not carry its standing player: rode="+p.RodeDrone+" state="+p.State+" pos="+go.transform.position+" expected="+(standing+Vector3.forward*.4f)+" deck="+drone.deck.bounds+" velocity="+motor.Velocity);cases.Add("The moving drone carries a player standing on its metal deck");
   var ordinary=Box("Collision wall",go.transform.position+Vector3.right*2,new Vector3(.3f,8,8));Physics.SyncTransforms();float wallX=ordinary.GetComponent<Collider>().bounds.min.x;motor.Launch(Vector3.right*10);motor.Tick(.5f);Check(go.transform.position.x<wallX,"Launch tunneled through a solid wall");cases.Add("CharacterController collision constrains launched movement");
   p.SetCheckpoint(origin+new Vector3(0,3,30),Quaternion.identity,"Validation");p.Respawn();Check(Vector3.Distance(go.transform.position,origin+new Vector3(0,3,30))<.01f&&motor.Velocity.magnitude<.01f,"Checkpoint reset did not clear momentum");Check(p.TryComplete(),"Completed mechanics did not unlock the finish");cases.Add("Checkpoint reset clears momentum and all five mechanics unlock completion");
   var data=new{passed=true,cases=cases.ToArray(),launchVelocity=launch.ToString("R"),windVerticalSpeed=inWind,crystalModels=Directory.GetFiles("Assets/Game/Environment/crystal/Models","*.fbx").Length};File.WriteAllText("Docs/CrystalParkour/Validation/MechanicReport.json",Newtonsoft.Json.JsonConvert.SerializeObject(data,Newtonsoft.Json.Formatting.Indented));return data;
  }
  finally{if(wind)Call(wind,"OnDisable");if(p)Call(p,"OnDisable");if(combat){combat.Cancel();if(combat.actions&&combat.actions.motion)combat.actions.motion.ReleaseGraph();}SceneManager.SetActiveScene(previous);EditorSceneManager.CloseScene(scene,true);}
 }
}
